#import <Cocoa/Cocoa.h>
#import <PDFKit/PDFKit.h>
int main(int argc,const char**argv){@autoreleasepool{PDFDocument*d=[[PDFDocument alloc]initWithURL:[NSURL fileURLWithPath:[NSString stringWithUTF8String:argv[1]]]];NSImage*i=[[d pageAtIndex:0]thumbnailOfSize:NSMakeSize(9500,6800) forBox:kPDFDisplayBoxMediaBox];NSBitmapImageRep*r=[NSBitmapImageRep imageRepWithData:[i TIFFRepresentation]];CGImageRef full=r.CGImage;double sx=CGImageGetWidth(full)/1189.0,sy=CGImageGetHeight(full)/841.0;double box[4][4]={{40,390,410,155},{180,550,260,110},{40,350,410,50},{475,250,590,340}};NSArray*names=@[@"main-pre-view.png",@"quiet-ldo-view.png",@"input-view.png",@"digital-view.png"];for(int n=0;n<4;n++){CGImageRef c=CGImageCreateWithImageInRect(full,CGRectMake(box[n][0]*sx,box[n][1]*sy,box[n][2]*sx,box[n][3]*sy));NSBitmapImageRep*cr=[[NSBitmapImageRep alloc]initWithCGImage:c];[[cr representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:[[NSString stringWithUTF8String:argv[2]]stringByAppendingPathComponent:names[n]]atomically:YES];CGImageRelease(c);}return 0;}}